scroll_frame_sequence.js:
const canvas = el.querySelector('canvas');
const ctx = canvas.getContext('2d');
const frameCount = parseInt(el.dataset.frames);
const frames = [];
const currentFrame = { value: 0 };

function loadFrame(i) {
  return new Promise(resolve => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.src = `${el.dataset.framePath}/frame_${String(i+1).padStart(4,'0')}.webp`;
  });
}

async function preload() {
  for (let i = 0; i < Math.min(10, frameCount); i++) {
    frames[i] = await loadFrame(i);
  }
  render();
  for (let i = 10; i < frameCount; i++) {
    frames[i] = await loadFrame(i);
  }
}

function render() {
  if (frames[Math.round(currentFrame.value)]) {
    canvas.width = frames[0].width;
    canvas.height = frames[0].height;
    ctx.drawImage(frames[Math.round(currentFrame.value)], 0, 0);
  }
}

gsap.to(currentFrame, {
  value: frameCount - 1,
  ease: 'none',
  onUpdate: render,
  scrollTrigger: { trigger: el, start: 'top top', end: '+=300%', scrub: 0.3, pin: true }
});

preload();

