preloader.js:
const preloader = document.getElementById('preloader');
const progress = preloader.querySelector('.preloader-progress');
let loaded = 0;
const total = document.images.length || 1;

function updateProgress() {
  loaded++;
  const pct = (loaded / total) * 100;
  gsap.to(progress, { width: pct + '%', duration: 0.3 });
  if (loaded >= total) closePreloader();
}

function closePreloader() {
  gsap.to(progress, { width: '100%', duration: 0.3, onComplete: () => {
    gsap.to(preloader, {
      yPercent: -100,
      duration: 0.8,
      ease: 'power3.inOut',
      delay: 0.3,
      onComplete: () => {
        preloader.remove();
        document.body.classList.add('loaded');
        // Trigger hero animation sequence
      }
    });
  }});
}

Array.from(document.images).forEach(img => {
  if (img.complete) updateProgress();
  else { img.addEventListener('load', updateProgress); img.addEventListener('error', updateProgress); }
});

setTimeout(() => closePreloader(), 5000); // Fallback

